import csv
import io


def _parse_row(row):
    for field in ('sku', 'name', 'qty'):
        value = row.get(field)
        if not isinstance(value, str):
            raise ValueError('invalid row, missing %s: %r' % (field, row))
    sku = row['sku'].strip()
    name = row['name'].strip()
    qty = row['qty'].strip()
    if not sku:
        raise ValueError('invalid row, empty sku: %r' % row)
    if not name:
        raise ValueError('invalid row, empty name: %r' % row)
    if not qty or any(ch < '0' or ch > '9' for ch in qty):
        raise ValueError('invalid row, qty must be decimal digits: %r' % row)
    return {'sku': sku, 'name': name, 'qty': int(qty)}


def import_text(text, store, dry_run=False):
    items = []
    seen = set()
    for row in csv.DictReader(io.StringIO(text)):
        item = _parse_row(row)
        if item['sku'] in seen:
            raise ValueError('invalid row, duplicate sku: %r' % item['sku'])
        seen.add(item['sku'])
        items.append(item)
    result = {'created': 0, 'updated': 0, 'unchanged': 0, 'changes': []}
    for item in items:
        before = store.get(item['sku'])
        if before == item:
            result['unchanged'] += 1
            continue
        result['created' if before is None else 'updated'] += 1
        result['changes'].append({'sku': item['sku'], 'before': before, 'after': item})
        if not dry_run:
            store.put(item)
    return result

